import { defineStore } from 'pinia'

export const useBuilderStore = defineStore('builder', () => {
  // Global toggle for Edit Mode (ON / OFF)
  const isEditMode = ref(false)

  // Selected block / menu in active edit
  const activeSelectedId = ref<string | null>(null)

  function toggleEditMode() {
    isEditMode.value = !isEditMode.value
    if (!isEditMode.value) {
      activeSelectedId.value = null
    }
  }

  function setEditMode(state: boolean) {
    isEditMode.value = state
    if (!state) {
      activeSelectedId.value = null
    }
  }

  function setSelectedId(id: string | null) {
    activeSelectedId.value = id
  }

  return {
    isEditMode,
    activeSelectedId,
    toggleEditMode,
    setEditMode,
    setSelectedId
  }
})
import { defineStore } from 'pinia'

export interface UserProfile {
  id: string
  email: string
  name: string
  role: 'SUPERADMIN' | 'ADMIN' | 'KASIR' | 'OPERATOR' | 'KURIR'
  outletName: string
  avatarUrl?: string
}

export const useAuthStore = defineStore('auth', () => {
  const user = ref<UserProfile>({
    id: 'usr-admin-01',
    email: 'admin1@yopmail.com',
    name: 'Admin Laundry',
    role: 'ADMIN',
    outletName: 'Laundry Express Pusat'
  })

  const isAuthenticated = computed(() => !!user.value)
  const isAdmin = computed(() => user.value?.role === 'ADMIN' || user.value?.role === 'SUPERADMIN')

  function updateUser(updated: Partial<UserProfile>) {
    if (user.value) {
      user.value = { ...user.value, ...updated }
    }
  }

  return {
    user,
    isAuthenticated,
    isAdmin,
    updateUser
  }
})
